def restore_safari_land_text(path,source):
    if str(path)!="src/data/wild_encounters.json":return source
    for label,original in ORIGINAL_SAFARI_LAND.items():
        i=source.index('"mons": [',source.index('"base_label": "'+label+'"'))
        current=BALANCED_SAFARI_LAND[label]
        assert source[i:i+len(current)]==current,label
        source=source[:i]+original+source[i+len(current):]
    return source
def prior_safari_land_source(path):
    return restore_safari_land_text(path,prior_kanto_interiors_source(path).decode("utf-8")).encode("utf-8")
def restore_prior_safari_land_text(path,source):
    return restore_safari_land_text(path,restore_prior_kanto_interiors_text(path,source))
